// 无 BC 显卡上 BC1–5 与 BC7 的 GPU 解压核 bcd（nvn_mtl.m 上传冲刷时派发；单测 graphics/nvn/tests/t_bcd_gpu.m 对 bcdec 逐纹素比）。
// 来源：MacNativeGames（https://github.com/ly05010419/MacNativeGames，MIT）games/wonder/third_party/d2r_gfx/gfx/nvn/nvn_mtl.m 的 k_bcd_msl，提交 84eebcd0985c，原样带入（只去掉 3D 版 bcd3）；BC7 段（S2Arm #582）照 bcdec_bc7 移植。
// The kernel bcd that decompresses BC1–5 and BC7 on GPUs without BC (dispatched at upload flush in nvn_mtl.m; graphics/nvn/tests/t_bcd_gpu.m compares it texel by texel with bcdec).
#pragma once
static const char k_bcd_msl[] =
"#include <metal_stdlib>\nusing namespace metal;\n"
"struct P { uint off, pitch, w, h, fmt, z; };\n"   // fmt: 1 BC1, 2 BC2, 3 BC3, 4 BC4, 5 BC4 signed, 6 BC5, 7 BC5 signed, 8 BC7
"static float3 c565(uint c) { return float3((c >> 11) & 31, (c >> 5) & 63, c & 31) / float3(31, 63, 31); }\n"
"static void col(device const uchar *b, thread float4 *o, bool four) {\n"
"  uint c0 = b[0] | (b[1] << 8), c1 = b[2] | (b[3] << 8), ix = b[4] | (b[5] << 8) | (b[6] << 16) | (b[7] << 24); float3 e0 = c565(c0), e1 = c565(c1); float4 p[4];\n"
"  p[0] = float4(e0, 1); p[1] = float4(e1, 1);\n"
"  if (four || c0 > c1) { p[2] = float4((2 * e0 + e1) / 3, 1); p[3] = float4((e0 + 2 * e1) / 3, 1); } else { p[2] = float4((e0 + e1) / 2, 1); p[3] = float4(0); }\n"
"  for (int i = 0; i < 16; i++) o[i] = p[(ix >> (2 * i)) & 3]; }\n"
"static void a8(device const uchar *b, thread float *o, bool sn) {\n"   // a single-channel block: BC4, the alpha of BC3, each half of BC5
"  float a0 = sn ? max(float(as_type<char>(b[0])), -127.0) / 127 : b[0] / 255.0, a1 = sn ? max(float(as_type<char>(b[1])), -127.0) / 127 : b[1] / 255.0;\n"
"  bool eight = sn ? as_type<char>(b[0]) > as_type<char>(b[1]) : b[0] > b[1]; float lo = sn ? -1 : 0; float p[8]; p[0] = a0; p[1] = a1;\n"
"  for (int k = 2; k < 8; k++) p[k] = eight ? ((8 - k) * a0 + (k - 1) * a1) / 7 : (k < 6 ? ((6 - k) * a0 + (k - 1) * a1) / 5 : (k == 6 ? lo : 1));\n"
"  uint lo24 = b[2] | (b[3] << 8) | (b[4] << 16), hi24 = b[5] | (b[6] << 8) | (b[7] << 16);\n"
"  for (int i = 0; i < 16; i++) o[i] = p[i < 8 ? (lo24 >> (3 * i)) & 7 : (hi24 >> (3 * (i - 8))) & 7]; }\n"
// BC7 (fmt 8): bcdec_bc7 移植为整数运算，逐纹素与 bcdec 完全一致；分区表 = bcdec partition_sets 压成每纹素 2 位（k_p2 / k_p3），锚点纹素成位掩码（k_f2 / k_f3）
// BC7 (fmt 8): bcdec_bc7 ported with the same integer arithmetic, so every texel equals bcdec; the partition tables are bcdec's partition_sets packed 2 bits per texel (k_p2 / k_p3), anchor texels as bit masks (k_f2 / k_f3)
"constant uint k_p2[64] = {\n"
"  0x50505050, 0x40404040, 0x54545454, 0x54505040, 0x50404000, 0x55545450, 0x55545040, 0x54504000, 0x50400000, 0x55555450, 0x55544000, 0x54400000, 0x55555440, 0x55550000, 0x55555500, 0x55000000,\n"
"  0x55150100, 0x4054, 0x15010000, 0x405054, 0x4050, 0x15050100, 0x5010000, 0x40505054, 0x404050, 0x5010100, 0x14141414, 0x5141450, 0x1155440, 0x555500, 0x15014054, 0x5414150,\n"
"  0x44444444, 0x55005500, 0x11441144, 0x5055050, 0x5500550, 0x11114444, 0x41144114, 0x44111144, 0x15055054, 0x1055040, 0x5041050, 0x5455150, 0x14414114, 0x50050550, 0x41411414, 0x141400,\n"
"  0x41504, 0x105410, 0x10541000, 0x4150400, 0x50410514, 0x41051450, 0x5415014, 0x14054150, 0x41050514, 0x41505014, 0x40011554, 0x54150140, 0x50505500, 0x555050, 0x15151010, 0x54540404\n"
"};\n"
"constant ushort k_f2[64] = {\n"
"  0x8001, 0x8001, 0x8001, 0x8001, 0x8001, 0x8001, 0x8001, 0x8001, 0x8001, 0x8001, 0x8001, 0x8001, 0x8001, 0x8001, 0x8001, 0x8001,\n"
"  0x8001, 0x5, 0x101, 0x5, 0x5, 0x101, 0x101, 0x8001, 0x5, 0x101, 0x5, 0x5, 0x101, 0x101, 0x5, 0x5,\n"
"  0x8001, 0x8001, 0x41, 0x101, 0x5, 0x101, 0x8001, 0x8001, 0x5, 0x101, 0x5, 0x5, 0x5, 0x8001, 0x8001, 0x41,\n"
"  0x41, 0x5, 0x41, 0x101, 0x8001, 0x8001, 0x5, 0x5, 0x8001, 0x8001, 0x8001, 0x8001, 0x8001, 0x5, 0x5, 0x8001\n"
"};\n"
"constant uint k_p3[64] = {\n"
"  0xaa685050, 0x6a5a5040, 0x5a5a4200, 0x5450a0a8, 0xa5a50000, 0xa0a05050, 0x5555a0a0, 0x5a5a5050, 0xaa550000, 0xaa555500, 0xaaaa5500, 0x90909090, 0x94949494, 0xa4a4a4a4, 0xa9a59450, 0x2a0a4250,\n"
"  0xa5945040, 0xa425054, 0xa5a5a500, 0x55a0a0a0, 0xa8a85454, 0x6a6a4040, 0xa4a45000, 0x1a1a0500, 0x50a4a4, 0xaaa59090, 0x14696914, 0x69691400, 0xa08585a0, 0xaa821414, 0x50a4a450, 0x6a5a0200,\n"
"  0xa9a58000, 0x5090a0a8, 0xa8a09050, 0x24242424, 0xaa5500, 0x24924924, 0x24499224, 0x50a50a50, 0x500aa550, 0xaaaa4444, 0x66660000, 0xa5a0a5a0, 0x50a050a0, 0x69286928, 0x44aaaa44, 0x66666600,\n"
"  0xaa444444, 0x54a854a8, 0x95809580, 0x96969600, 0xa85454a8, 0x80959580, 0xaa141414, 0x96960000, 0xaaaa1414, 0xa05050a0, 0xa0a5a5a0, 0x96000000, 0x40804080, 0xa9a8a9a8, 0xaaaaaa44, 0x2a4a5254\n"
"};\n"
"constant ushort k_f3[64] = {\n"
"  0x8009, 0x109, 0x8101, 0x8009, 0x8101, 0x8009, 0x8009, 0x8101, 0x8101, 0x8101, 0x8041, 0x8041, 0x8041, 0x8021, 0x8009, 0x109,\n"
"  0x8009, 0x109, 0x8101, 0x8009, 0x8009, 0x109, 0x8041, 0x501, 0x29, 0x8101, 0x141, 0x441, 0x8101, 0x8021, 0x8401, 0x8101,\n"
"  0x8101, 0x8009, 0x8009, 0x421, 0x441, 0x501, 0x301, 0x8401, 0x8041, 0x8009, 0x8101, 0x8021, 0x8009, 0x8041, 0x8041, 0x8101,\n"
"  0x8009, 0x8009, 0x8021, 0x8021, 0x8021, 0x8101, 0x8021, 0x8401, 0x8021, 0x8401, 0x8101, 0xa001, 0x8009, 0x9001, 0x8009, 0x109\n"
"};\n"
"constant uchar k_w2[4] = {0, 21, 43, 64}, k_w3[8] = {0, 9, 18, 27, 37, 46, 55, 64}, k_w4[16] = {0, 4, 9, 13, 17, 21, 26, 30, 34, 38, 43, 47, 51, 55, 60, 64};\n"
"constant uchar k_cb[8] = {4, 6, 5, 7, 5, 7, 7, 5}, k_ab[8] = {0, 0, 0, 0, 6, 8, 7, 5};\n"
"static uint rb(thread const uint *q, thread uint &pos, uint n) { uint w = pos >> 5, s = pos & 31, v = q[w] >> s; if (s + n > 32) v |= q[w + 1] << (32 - s); pos += n; return v & ((1u << n) - 1); }\n"
"static uint wt(uint n, uint i) { return n == 2 ? k_w2[i] : n == 3 ? k_w3[i] : k_w4[i]; }\n"
"static uint lerp7(uint a, uint b, uint w) { return (a * (64 - w) + b * w + 32) >> 6; }\n"
"static void bc7(device const uchar *b, thread float4 *o) {\n"
"  uint q[4]; for (int i = 0; i < 4; i++) q[i] = b[4 * i] | (b[4 * i + 1] << 8) | (b[4 * i + 2] << 16) | (b[4 * i + 3] << 24);\n"
"  uint m = 0; while (m < 8 && !((q[0] >> m) & 1)) m++;\n"
"  if (m >= 8) { for (int i = 0; i < 16; i++) o[i] = float4(0); return; }\n"
"  uint pos = m + 1, ns = (m == 0 || m == 2) ? 3 : (m == 1 || m == 3 || m == 7) ? 2 : 1, part = ns > 1 ? rb(q, pos, m == 0 ? 4 : 6) : 0, rot = 0, isb = 0;\n"
"  if (m == 4 || m == 5) { rot = rb(q, pos, 2); if (m == 4) isb = rb(q, pos, 1); }\n"
"  uint ne = ns * 2, cb = k_cb[m], ab = k_ab[m], pb = (0xcbu >> m) & 1, e[6][4];\n"
"  for (uint c = 0; c < 3; c++) for (uint j = 0; j < ne; j++) e[j][c] = rb(q, pos, cb);\n"
"  for (uint j = 0; j < ne; j++) e[j][3] = ab ? rb(q, pos, ab) : 0;\n"
"  if (m == 1) { uint p0 = rb(q, pos, 1), p1 = rb(q, pos, 1); for (uint c = 0; c < 3; c++) { e[0][c] = e[0][c] << 1 | p0; e[1][c] = e[1][c] << 1 | p0; e[2][c] = e[2][c] << 1 | p1; e[3][c] = e[3][c] << 1 | p1; } }\n"
"  else if (pb) for (uint j = 0; j < ne; j++) { uint p1 = rb(q, pos, 1); for (uint c = 0; c < 4; c++) e[j][c] = e[j][c] << 1 | p1; }\n"
"  for (uint j = 0; j < ne; j++) { for (uint c = 0; c < 4; c++) { uint n = (c < 3 ? cb : ab) + pb; e[j][c] = c == 3 && !ab ? 255 : (e[j][c] << (8 - n)) | ((e[j][c] << (8 - n)) >> n); } }\n"
"  uint ib = m < 2 ? 3 : m == 6 ? 4 : 2, ib2 = m == 4 ? 3 : m == 5 ? 2 : 0, pp = ns == 2 ? k_p2[part] : ns == 3 ? k_p3[part] : 0, fx = ns == 2 ? k_f2[part] : ns == 3 ? k_f3[part] : 1, ix[16];\n"
"  for (uint t = 0; t < 16; t++) ix[t] = rb(q, pos, ib - ((fx >> t) & 1));\n"
"  for (uint t = 0; t < 16; t++) { uint s = (pp >> (2 * t)) & 3, ci = ix[t], cn = ib, ai = ix[t], an = ib;\n"
"    if (ib2) { uint i2 = rb(q, pos, t ? ib2 : ib2 - 1); if (isb) { ci = i2; cn = ib2; } else { ai = i2; an = ib2; } }\n"
"    uint r = lerp7(e[2 * s][0], e[2 * s + 1][0], wt(cn, ci)), g = lerp7(e[2 * s][1], e[2 * s + 1][1], wt(cn, ci)), bl = lerp7(e[2 * s][2], e[2 * s + 1][2], wt(cn, ci)), a = lerp7(e[2 * s][3], e[2 * s + 1][3], wt(an, ai)), x;\n"
"    if (rot == 1) { x = a; a = r; r = x; } else if (rot == 2) { x = a; a = g; g = x; } else if (rot == 3) { x = a; a = bl; bl = x; }\n"
"    o[t] = float4(r, g, bl, a) / 255.0; } }\n"
"static void dec(device const uchar *src, device const P &p, uint2 g, thread float4 *o) {\n"
"  uint bb = (p.fmt == 1 || p.fmt == 4 || p.fmt == 5) ? 8 : 16; device const uchar *b = src + p.off + g.y * p.pitch + g.x * bb; float a[16], c[16];\n"
"  if (p.fmt == 1) col(b, o, false);\n"
"  else if (p.fmt == 2) { col(b + 8, o, true); for (int i = 0; i < 16; i++) o[i].a = ((b[i / 2] >> (4 * (i & 1))) & 15) / 15.0; }\n"
"  else if (p.fmt == 3) { col(b + 8, o, true); a8(b, a, false); for (int i = 0; i < 16; i++) o[i].a = a[i]; }\n"
"  else if (p.fmt == 4 || p.fmt == 5) { a8(b, a, p.fmt == 5); for (int i = 0; i < 16; i++) o[i] = float4(a[i], 0, 0, 1); }\n"
"  else if (p.fmt == 8) bc7(b, o);\n"
"  else { a8(b, a, p.fmt == 7); a8(b + 8, c, p.fmt == 7); for (int i = 0; i < 16; i++) o[i] = float4(a[i], c[i], 0, 1); } }\n"
"kernel void bcd(device const uchar *src [[buffer(0)]], device const P &p [[buffer(1)]], texture2d<float, access::write> dst [[texture(0)]], uint2 g [[thread_position_in_grid]]) {\n"
"  if (g.x >= (p.w + 3) / 4 || g.y >= (p.h + 3) / 4) return; float4 o[16]; dec(src, p, g, o);\n"
"  for (int i = 0; i < 16; i++) { uint2 q = g * 4 + uint2(i & 3, i >> 2); if (q.x < p.w && q.y < p.h) dst.write(o[i], q); } }\n";
